import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"]
    events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    high_ts = None
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]

    # Only events strictly after the watermark need to be applied;
    # events at/before the watermark are already reflected in target_snapshot.
    if high_ts is not None and pd.notna(high_ts):
        ev = events[events["event_ts"] > high_ts].copy()
    else:
        ev = events.copy()

    # Deterministic sequential application order per item: (event_ts, event_seq)
    ev = ev.sort_values(["item_id", "event_ts", "event_seq"], kind="mergesort")

    # Initialize state from target_snapshot
    state = {}
    for row in target.itertuples(index=False):
        state[row.item_id] = {
            "qty": float(row.qty_on_hand),
            "ts": row.last_event_ts,
            "present": True,
        }

    for row in ev.itertuples(index=False):
        iid = row.item_id
        op = row.op
        qty = row.qty
        ts = row.event_ts

        if iid not in state:
            state[iid] = {"qty": 0.0, "ts": None, "present": False}

        s = state[iid]

        if op == "R":
            if not s["present"]:
                s["qty"] = 0.0
            s["qty"] = s["qty"] + qty
            s["present"] = True
            s["ts"] = ts
        elif op == "A":
            s["qty"] = qty
            s["present"] = True
            s["ts"] = ts
        elif op == "D":
            s["present"] = False
            s["qty"] = 0.0
            s["ts"] = ts

    rows = []
    for iid, s in state.items():
        if s["present"]:
            rows.append(
                {
                    "item_id": iid,
                    "qty_on_hand": s["qty"],
                    "last_event_ts": s["ts"],
                }
            )

    out = pd.DataFrame(rows, columns=["item_id", "qty_on_hand", "last_event_ts"])

    if len(out) > 0:
        out = out.sort_values("item_id", kind="mergesort").reset_index(drop=True)
        out["item_id"] = out["item_id"].astype("int64")
        out["qty_on_hand"] = out["qty_on_hand"].astype("float64")
        out["last_event_ts"] = pd.to_datetime(out["last_event_ts"]).astype(
            "datetime64[us]"
        )
    else:
        out = pd.DataFrame(
            {
                "item_id": pd.Series(dtype="int64"),
                "qty_on_hand": pd.Series(dtype="float64"),
                "last_event_ts": pd.Series(dtype="datetime64[us]"),
            }
        )

    return {"new_snapshot": out}
